    out = [row[:] for row in grid]
    seen = set()
    components = []

    # Find 4-connected objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    owner = {cell: i for i, comp in enumerate(components) for cell in comp}
    targets = set()
    rows = [r for r in range(h) if grid[r][0] == 1 or grid[r][w-1] == 1]
    cols = [c for c in range(w) if grid[0][c] == 1 or grid[h-1][c] == 1]

    # Each edge marker's ray selects the first 2-object it meets.
    for r in rows:
        for start, step in ((0, 1), (w-1, -1)):
            for c in range(start, w if step == 1 else -1, step):
                if grid[r][c] == 2:
                    targets.add(owner[(r, c)])
                    break
    for c in cols:
        for start, step in ((0, 1), (h-1, -1)):
            for r in range(start, h if step == 1 else -1, step):
                if grid[r][c] == 2:
                    targets.add(owner[(r, c)])
                    break

    for i in targets:
        for r, c in components[i]:
            out[r][c] = 1
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out
